import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_def = sum(1 for a in op if a == 'D')
    last_op = op[-1]
    last_my = my[-1]

    # Track trailing runs of opponent defections and cooperations.
    run_def = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            run_def += 1
        else:
            break
    run_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            run_c += 1
        else:
            break

    # Unbroken cooperation: preserve mutual cooperation.
    if opp_def == 0:
        # Very light late probing only if we've never been punished.
        if n >= 92 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Opponent defected last round.
    if last_op == 'D':
        # Long defection streaks: punish consistently to discourage exploitation.
        if run_def >= 3:
            return 'D'
        # If we just punished and they defected again, keep punishing.
        if last_my == 'D':
            return 'D'
        # Single or double defection: retaliate once to signal displeasure.
        return 'D'

    # Opponent cooperated last round.
    # If we defected last round, return to cooperation to repair.
    if last_my == 'D':
        # Unless opponent has been heavily defecting overall.
        if opp_def * 2 > n:
            if rng.random() < 0.6:
                return 'D'
        return 'C'

    # Both cooperated recently. Look at recent window.
    if n >= 10:
        recent = op[-10:]
        recent_def = sum(1 for a in recent if a == 'D')
        if recent_def == 0:
            return 'C'
        if recent_def <= 2:
            # Mostly cooperative; preserve cooperation.
            return 'C'
        if recent_def >= 6:
            return 'D'
        # Mixed zone: mostly cooperate, occasional safe defection when ahead.
        if rng.random() < 0.2:
            return 'D'
        return 'C'

    # Early/mid game default: cooperate to build mutual cooperation.
    return 'C'
